using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckTugOfWar {
public enum TugStage{Countdown,Pull,Defeat,Replay,RoundResult}
public sealed class TugMatch:SportsEventSession {
 public SportsEventTruck[] trucks;public Rigidbody[] headers;public LineRenderer[] ropes;public SportsEventCamera broadcast;public SportsMotionReplay replay;public SportsCameraFit fit;public SportsChaosWeather atmosphere;public TugRuts ruts;public SportsFragmentRig[] fragments;public ParticleSystem[] fire;public float edge=10,roundLimit=80;
 public TugStage Stage{get;private set;}public float Clock{get;private set;}public float Timer{get;private set;}public int Heat{get;private set;}public int[] wins=new int[2];public int HeatWinner{get;private set;}=-1;public int Winner{get;private set;}=-1;public int Draws{get;private set;}public int Heaves{get;private set;}public float Tension=>connection!=null?connection.currentForce.magnitude:0;public float Advantage=>Mathf.Abs(headers[1].position.x)-Mathf.Abs(headers[0].position.x);
 SpringJoint connection;readonly SpringJoint[] ties=new SpringJoint[8];readonly bool[] eased=new bool[8],heaved=new bool[8],qte=new bool[8],burned=new bool[8];readonly float[] boost=new float[8],spin=new float[8];readonly int[] cycle=new int[8];readonly StringBuilder text=new StringBuilder(800);string notice="";bool skip;float replayAge;
 public int Team(int slot)=>slot<teamA?0:1;public int Side(int team)=>((Heat&1)==1?1:-1)*(team==0?-1:1);public int Direction(int slot)=>((Heat+slot+cycle[slot])&1)==0?-1:1;public float Phase=>Mathf.Repeat(Clock,6);
 public override string Title=>"MOUNTAIN TUG OF WAR";public override int MinimumPlayers=>2;public override int MaximumPlayers=>8;public override bool TeamSport=>true;public override int OptionCount=>2;public override int WeatherCount=>1;public override string OptionLabel=>option==0?"MANUAL HEAVE TIMING":"TIMING ASSIST";public override bool ReplayControls=>Stage==TugStage.Replay;
 public override string Help=>"FIRST TO THREE · MOUNTAIN TUG\nTeams of one to four face across a lava chasm and reverse away from the edge. Up to four humans; AI fills either team. Sides swap each round.\n\nHold REVERSE for baseline pull. In each six-second cycle, EASE OFF between1.8 and2.35seconds, then reapply REVERSE between2.35 and2.85 for a stronger heave. The on-screen signal counts the timing. At3–3.8seconds steer the shown LEFT/RIGHT to brace the heave. A missed cue briefly causes wheelspin. Timing Assist accepts a held reverse during the heave window and widens bracing; it applies equally to AI. Small steering adjustments reposition your truck; the physical tow ropes limit travel.\n\nNWH wheels provide all pulling traction. One physical central rope connects the team headers; no hidden team boost or rubber band. Mud ruts persist through the round. A team's first chassis crossing the clearly marked ledge edge, or actually falling below it, loses the round. Same-step losses draw. At80seconds the team that gained at least2.5feet more ground wins; a closer result is an explicit draw and replay. Result locks before the lava finale. Winners are secured; losing trucks fall physically. Recorded flight replays have angle, speed, rewind and skip. Pause/reconnect preserves everything. Offline only.";
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="Up to four local humans; other seats use AI.";return false;}return true;}
 public override string Header=>Title+" · ROUND "+Heat+" · "+wins[0]+" : "+wins[1]+" · "+(Stage==TugStage.Pull?(roundLimit-Clock).ToString("F0")+"s":Stage==TugStage.Countdown?Mathf.CeilToInt(Timer).ToString():Stage.ToString().ToUpperInvariant());
 public override string Status=>Stage!=TugStage.Pull?notice:Phase<1.8f?"REVERSE · BUILD TENSION":Phase<2.35f?"EASE OFF":Phase<2.85f?"HEAVE! REAPPLY REVERSE":Phase<3.8f?"BRACE · FOLLOW YOUR DIRECTION":"REVERSE · NEXT HEAVE SOON";
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append("  TEAM ").Append(Team(i)+1).Append(" · ").Append(wins[Team(i)]).Append(" / 3 · ").Append(spin[i]>0?"WHEELSPIN":boost[i]>0?"HEAVE!":"BRACE "+(Direction(i)<0?"LEFT":"RIGHT")).Append('\n');return text.ToString();}}
 public override string Results=>(Winner<0?"MATCH COMPLETE":"TEAM "+(Winner+1)+" WINS THE MOUNTAIN")+"\n\n"+Standings+"\nDrawn rounds: "+Draws;
 protected override void BeginGame(){wins[0]=wins[1]=0;Winner=-1;atmosphere.Configure(19321,1,0);Heat=1;Draws=Heaves=0;replay.Colorize(Array.ConvertAll(setup.players,p=>p.color));BeginHeat();}
 void DisconnectRopes(){if(connection!=null){connection.connectedBody=null;Destroy(connection);connection=null;}for(int i=0;i<ties.Length;i++)if(ties[i]!=null){ties[i].connectedBody=null;Destroy(ties[i]);ties[i]=null;}}
 public static SpringJoint Rope(Rigidbody from,Rigidbody to,Vector3 anchor,Vector3 connected,float length,float spring=240,float damper=36){var joint=from.gameObject.AddComponent<SpringJoint>();joint.autoConfigureConnectedAnchor=false;joint.connectedBody=to;joint.anchor=anchor;joint.connectedAnchor=connected;joint.minDistance=0;joint.maxDistance=length;joint.spring=spring;joint.damper=damper;joint.tolerance=.025f;joint.enableCollision=false;joint.massScale=joint.connectedMassScale=1;return joint;}
 void BeginHeat(){ruts.ResetRuts();DisconnectRopes();replay.End();Clock=0;Timer=3;Stage=TugStage.Countdown;HeatWinner=-1;skip=false;notice="TAKE THE STRAIN";for(int team=0;team<2;team++){var h=headers[team];h.isKinematic=true;h.position=new Vector3(Side(team)*13,.7f,0);h.rotation=Quaternion.identity;h.transform.SetPositionAndRotation(h.position,h.rotation);h.gameObject.SetActive(true);}for(int i=0;i<8;i++){trucks[i].gameObject.SetActive(i<setup.count);if(i>=setup.count)continue;int team=Team(i),n=team==0?i:i-teamA,count=team==0?teamA:teamB;var t=trucks[i];fragments[i].ResetBody();t.Prepare(new Vector3(Side(team)*(16+n/2*4),.7f,(n-(count-1)*.5f)*3.5f),Quaternion.LookRotation(Vector3.right*-Side(team)));t.Power(false);t.body.isKinematic=true;boost[i]=spin[i]=0;eased[i]=heaved[i]=qte[i]=burned[i]=false;cycle[i]=-1;fire[i].Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}for(int i=0;i<ropes.Length;i++)ropes[i].enabled=i==0||i-1<setup.count;replay.ResetRecord();Gate();}
 void Release(){for(int t=0;t<2;t++){headers[t].isKinematic=false;headers[t].linearVelocity=headers[t].angularVelocity=Vector3.zero;}connection=Rope(headers[0],headers[1],Vector3.zero,Vector3.zero,26,320,48);for(int i=0;i<setup.count;i++){var t=trucks[i];t.body.isKinematic=false;t.Power(true);var anchor=new Vector3(0,.25f,1.35f);float length=Vector3.Distance(t.transform.TransformPoint(anchor),headers[Team(i)].position);ties[i]=Rope(t.body,headers[Team(i)],anchor,Vector3.zero,length,260,36);}Stage=TugStage.Pull;}
 Vector2 Bot(int i){float skill=(int)setup.players[i].difficulty;float error=(Mathf.Sin(i*71+Heat*13+cycle[i]*29)+1)*.5f;float phase=Phase;float offset=(1-skill*.35f)*.15f;bool mistake=error<(skill==0?.22f:skill==1?.1f:.035f);float y=phase>=1.86f+offset&&phase<2.38f+offset&&!mistake?0:-1;float x=phase>=3.08f+offset&&phase<3.7f?Direction(i)*(mistake?-1:1):Mathf.Clamp(-trucks[i].body.position.z*.12f,-.22f,.22f);return new Vector2(x,y);}
 void Pull(int i,Vector2 command,float dt){int current=(int)(Clock/6);if(cycle[i]!=current){cycle[i]=current;eased[i]=heaved[i]=qte[i]=false;}float phase=Phase;bool reverse=command.y<-.55f;if(phase>=1.8f&&phase<2.35f&&!reverse)eased[i]=true;if(phase>=2.35f&&phase<2.85f&&!heaved[i]&&reverse&&(eased[i]||option==1)){heaved[i]=true;boost[i]=.7f;Heaves++;feedback.Play(0,0,true);Pulse(i,.2f,.1f);}if(phase>=2.85f&&!heaved[i]&&spin[i]<=0){spin[i]=.8f;heaved[i]=true;}if(phase>=(option==1?2.9f:3)&&phase<(option==1?4.1f:3.8f)&&!qte[i]&&command.x*Direction(i)>(option==1?.4f:.55f)){qte[i]=true;boost[i]=Mathf.Max(boost[i],.65f);}if(phase>=(option==1?4.1f:3.8f)&&!qte[i]){spin[i]=.8f;qte[i]=true;}boost[i]=Mathf.Max(0,boost[i]-dt);spin[i]=Mathf.Max(0,spin[i]-dt);var t=trucks[i];t.motorTorque=boost[i]>0?13:7;t.grip=(spin[i]>0?.65f:1.55f)*(1-ruts.Depth(t.body.position)*.22f);t.TickDrive(new Vector2(command.x*.45f,command.y));}
 protected override void Simulate(float dt){atmosphere.Tick(Clock);if(Stage==TugStage.Countdown){Timer-=dt;if(Timer<=0)Release();return;}if(Stage==TugStage.Pull){Clock+=dt;bool[] lost={false,false};for(int i=0;i<setup.count;i++){var t=trucks[i];int team=Team(i);if(t.body.worldCenterOfMass.x*Side(team)<edge-.4f||t.body.worldCenterOfMass.y< -2)lost[team]=true;}if(lost[0]||lost[1]){Resolve(lost[0]&&lost[1]?-1:lost[0]?1:0,"EDGE CROSSED");return;}if(Clock>=roundLimit){Resolve(Mathf.Abs(Advantage)<.75f?-1:Advantage>0?1:0,"TIME · PHYSICAL GROUND GAINED");return;}for(int i=0;i<setup.count;i++)Pull(i,setup.players[i].source==BowlingSource.AI?Bot(i):commands[i],dt);replay.Record(Clock,(1<<setup.count)-1);return;}
 if(Stage==TugStage.Defeat){Clock+=dt;Timer-=dt;for(int i=0;i<setup.count;i++)if(HeatWinner>=0&&Team(i)!=HeatWinner&&!burned[i]){var t=trucks[i];t.body.AddForce(Vector3.right*(-Side(Team(i)))*8,ForceMode.Acceleration);if(t.body.position.y< -48){burned[i]=true;fire[i].transform.position=t.body.position;fire[i].Play();fragments[i].Burst();feedback.Play(3,0,true);}}replay.Record(Clock,(1<<setup.count)-1);if(Timer<=0){foreach(var t in trucks){t.Power(false);t.body.isKinematic=true;t.gameObject.SetActive(false);}foreach(var f in fragments)f.Freeze();Stage=TugStage.Replay;replayAge=0;replay.Begin(Mathf.Max(0,Clock-7));}return;}
 if(Stage==TugStage.Replay){replayAge+=dt;if(skip||replay.Step(dt)||replayAge>12){replay.End();Stage=TugStage.RoundResult;Timer=1.5f;}return;}Timer-=dt;if(Timer<=0){if(Winner>=0)EndMatch();else{Heat++;BeginHeat();}}}
 void Resolve(int team,string reason){if(Stage!=TugStage.Pull)return;HeatWinner=team;if(team>=0){wins[team]++;if(wins[team]>=3)Winner=team;notice="TEAM "+(team+1)+" WINS · "+reason;}else{Draws++;notice="DRAW · "+reason;}DisconnectRopes();foreach(var h in headers)h.isKinematic=true;for(int i=0;i<setup.count;i++){trucks[i].Power(false);if(team<0||Team(i)==team)trucks[i].body.isKinematic=true;}Timer=team<0?1:6;Stage=TugStage.Defeat;feedback.Play(5,0,true);}
 protected override void Present(float dt){if(broadcast==null)return;Vector3 focus=new Vector3(0,0,0);var offset=new Vector3(0,28,-43);if(Stage==TugStage.Replay&&replay.Playing){Vector3 p=Vector3.zero;int n=0;for(int i=0;i<setup.count;i++)if(Team(i)!=HeatWinner){p+=replay.Position(i);n++;}if(n>0)focus=p/n;offset=replay.Angle==1?new Vector3(18,13,-14):replay.Angle==2?new Vector3(-20,18,5):new Vector3(0,20,-35);}broadcast.Pose(focus,offset,58);if(Stage!=TugStage.Replay){fit.arenaBounds=new Bounds(new Vector3(-5,-1,0),new Vector3(73,9,24));fit.Apply();}if(ropes==null)return;for(int i=0;i<ropes.Length;i++){if(!ropes[i].enabled)continue;Vector3 a,b;if(i==0){a=headers[0].position;b=headers[1].position;}else{int slot=i-1;a=trucks[slot].transform.TransformPoint(new Vector3(0,.25f,1.35f));b=headers[Team(slot)].position;}var line=ropes[i];line.positionCount=17;float slack=Mathf.Clamp((Vector3.Distance(a,b)-2)*.012f,.05f,.6f);for(int k=0;k<17;k++){float t=k/16f;line.SetPosition(k,Vector3.Lerp(a,b,t)+Vector3.down*(Mathf.Sin(t*Mathf.PI)*slack));}line.enabled=Stage==TugStage.Pull||Stage==TugStage.Countdown;}}
 public override void ExtraAction(string key){if(Stage!=TugStage.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")skip=true;ConsumeActions();}
 protected override void SetPaused(bool paused){if(atmosphere!=null)atmosphere.Pause(paused);}protected override void StopGame(){DisconnectRopes();replay?.End();if(trucks!=null)foreach(var t in trucks)if(t!=null){t.Power(false);t.body.isKinematic=true;}if(headers!=null)foreach(var h in headers)if(h!=null)h.isKinematic=true;if(fragments!=null)foreach(var f in fragments)if(f!=null)f.Freeze();}protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)if(t!=null)t.StopSound();}
}}
